/// sun_radec of jb2008_density.m: the low-precision Sun's right ascension and declination [rad] (mean equinox of
/// date) at an MJD.
/// - mjd: real[1] (passed a plain number)
/// - returns ra: real[1] (passed a plain number)
/// - returns dec: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn sun_radec(mjd: f64) -> (f64, f64) {
    let mut ra: f64 = 0.0;
    let mut dec: f64 = 0.0;
    let mut t: f64 = ((mjd - 51544.5) / 36525.0);
    let mut l: f64 = crate::gen::timescales::omod((280.46 + (36000.771 * t)), 360.0);
    let mut m: f64 = crate::gen::timescales::deg2rad(crate::gen::timescales::omod((357.528 + (35999.05 * t)), 360.0));
    let mut lam: f64 = crate::gen::timescales::deg2rad(((l + (1.915 * f64::sin(m))) + (0.02 * f64::sin((2.0 * m)))));
    let mut eps: f64 = crate::gen::timescales::deg2rad((23.439 - (0.013 * t)));
    ra = crate::gen::timescales::omod(f64::atan2((f64::cos(eps) * f64::sin(lam)), f64::cos(lam)), (2.0 * core::f64::consts::PI));
    dec = f64::asin((f64::sin(eps) * f64::sin(lam)));
    (ra, dec)
}

/// gmst_rad of jb2008_density.m: the IAU 1982 GMST [rad] of an MJD.
/// - mjd: real[1] (passed a plain number)
/// - returns g: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn gmst_rad(mjd: f64) -> f64 {
    let mut g: f64 = 0.0;
    let mut tu: f64 = ((f64::floor(mjd) - 51544.5) / 36525.0);
    let mut gmst0: f64 = (((24110.54841 + (8640184.812866 * tu)) + (0.093104 * f64::powf(tu, core::hint::black_box(2.0)))) - (0.0000062 * f64::powf(tu, core::hint::black_box(3.0))));
    let mut fr: f64 = crate::gen::timescales::omod(mjd, 1.0);
    let mut gsec: f64 = crate::gen::timescales::omod((gmst0 + ((1.0027379093 * 86400.0) * fr)), 86400.0);
    g = crate::gen::timescales::deg2rad((gsec / 240.0));
    g
}

/// jb2008_density(t, lon_deg, lat_deg, alt_km) for one epoch (the in-RHS case, no decimation): the SET indices with the
/// spec's lags (F10 and S10 at t - 1 d, M10 at t - 2 d, Y10 at t - 5 d, DSTDTC at t), linear with extrapolation, the
/// Sun, GMST and the core. utc = [Y M D h m s].
/// - utc: real[1][6] (passed a plain number)
/// - lon_deg: real[1] (passed a plain number)
/// - lat_deg: real[1] (passed a plain number)
/// - alt_km: real[1] (passed a plain number)
/// - returns rho: real[1] (passed a plain number)
/// - returns out: JbOut (passed rec)
/// - returns inp: JbCoreInputs (passed rec)
#[allow(clippy::too_many_arguments)]
pub fn jb2008_density(utc: [f64; 6], lon_deg: f64, lat_deg: f64, alt_km: f64) -> (f64, JbOut, JbCoreInputs) {
    let mut rho: f64 = 0.0;
    let mut out: JbOut = JbOut::default();
    let mut inp: JbCoreInputs = JbCoreInputs::default();
    let mut dnum: f64 = crate::gen::timescales::datenum(utc[0], utc[1], utc[2], utc[3], utc[4], utc[5]);
    let mut mjd: f64 = (dnum - 678942.0);
    let mut f10: f64 = crate::gen::jb2008::sol_interp(0, (dnum - 1.0));
    let mut f10b: f64 = crate::gen::jb2008::sol_interp(1, (dnum - 1.0));
    let mut s10: f64 = crate::gen::jb2008::sol_interp(2, (dnum - 1.0));
    let mut s10b: f64 = crate::gen::jb2008::sol_interp(3, (dnum - 1.0));
    let mut m10: f64 = crate::gen::jb2008::sol_interp(4, (dnum - 2.0));
    let mut m10b: f64 = crate::gen::jb2008::sol_interp(5, (dnum - 2.0));
    let mut y10: f64 = crate::gen::jb2008::sol_interp(6, (dnum - 5.0));
    let mut y10b: f64 = crate::gen::jb2008::sol_interp(7, (dnum - 5.0));
    let mut dstdtc: f64 = crate::gen::jb2008::dtc_interp(dnum);
    let (mut ra_sun, mut dec_sun) = crate::gen::jb2008::sun_radec(mjd);
    let mut gmst: f64 = crate::gen::jb2008::gmst_rad(mjd);
    let mut ra_sat: f64 = crate::gen::timescales::omod((crate::gen::timescales::deg2rad(lon_deg) + gmst), (2.0 * core::f64::consts::PI));
    let mut lat_r: f64 = crate::gen::timescales::deg2rad(lat_deg);
    inp = JbCoreInputs::default();
    inp.mjd = mjd;
    inp.sun = [ra_sun, dec_sun];
    inp.sat = [ra_sat, lat_r, alt_km];
    inp.ind = [f10, f10b, s10, s10b, m10, m10b, y10, y10b, dstdtc];
    out = crate::gen::jb2008::jb2008_core(mjd, inp.sun, inp.sat, f10, f10b, s10, s10b, m10, m10b, y10, y10b, dstdtc);
    rho = out.rho;
    (rho, out, inp)
}
